import {
  type ProjectSortBy,
  type GetUpcomingProjectsData,
  type SortType,
  type UpcomingProjectType,
  getUpcomingProjects,
  type ProjectType,
} from '~/client';

export const useUpcomingProjectsList = defineQuery(() => {
  const route = useRoute();

  const params = computed<GetUpcomingProjectsData['query']>(() => {
    const urlParams = {
      page: Number(route.query.page) || 1,
      size: Number(route.query.size) || 10,
      sort_by: (route.query.sort_by as ProjectSortBy) || 'start_date',
      sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
      from_date: isDate((route.query.from_date as string) || '') ? (route.query.from_date as string) : undefined,
      name: (route.query.name as string) || undefined,
      project_type: (route.query.project_type as UpcomingProjectType) || 'all',
      type: (route.query.type as ProjectType) || undefined,
    } satisfies GetUpcomingProjectsData['query'];

    return Object.fromEntries(
      Object.entries(urlParams).filter(([_, value]) => value !== undefined)
    ) as GetUpcomingProjectsData['query'];
  });

  const { data, error, isLoading } = useQuery({
    key: () => ['applications.upcoming.list', params.value || ''],
    query: () => {
      return getUpcomingProjects({
        composable: '$fetch',
        query: ref(params.value),
      });
    },
    staleTime: 0,
  });

  return {
    params,
    upcomingProjects: data,
    applications: computed(() => data.value?.items ?? []),
    total: computed(() => data.value?.total ?? 0),
    error,
    isLoading,
  };
});
