<template>
  <section class="flex flex-col gap-4 md:gap-6">
    <PageTitle :title="title" show-doc>
      <NuxtLink v-if="isCanvasser" :to="{ name: 'applications-my' }">
        <Button>My Applications</Button>
      </NuxtLink>
      <FilterTabsNav v-else :items="filterTabs" rounded />
    </PageTitle>
    <ApplicationsFilters v-if="params" :params="params" />
    <AppLoader v-if="isLoading" subject="upcoming projects" />
    <AppError v-else-if="error" :error="error" title="Failed to load upcoming projects" />
    <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" />
    <AppEmpty v-else-if="isEmpty" subject="projects" />
    <section v-else class="flex flex-col gap-4">
      <ApplicationsItem v-for="item in applications" :key="item.id" :item="item" />
      <AppPagination :page="params.page" :size="params.size" :total="total" label="applications" />
    </section>
  </section>
</template>

<script setup lang="ts">
import { useUpcomingProjectsList } from '~/queries/applications/upcomingProjects';
import FilterTabsNav from '~/components/common/FilterTabsNav.vue';
import { upcomingProjectsGuidedEmpty, UPCOMING_FILTER_DEFAULTS } from '~/constants/guidedEmpty/applications';

const { isCanvasser } = useUserRole();
const route = useRoute();

const title = 'Upcoming Projects';

useHead({
  title: title,
});

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'applications',
});

const { applications, total, error, isLoading, params, upcomingProjects } = useUpcomingProjectsList();

const filterTabs = computed(() => {
  if (isCanvasser.value) {
    return [];
  } else {
    return [
      {
        label: 'All',
        to: { name: 'applications-upcoming', query: { ...route.query, page: 1, project_type: 'all' } },
        count: upcomingProjects.value?.total_count,
        selected: params.value.project_type === 'all' || !params.value.project_type,
      },
      {
        label: 'Active',
        to: { name: 'applications-upcoming', query: { ...route.query, page: 1, project_type: 'active' } },
        count: upcomingProjects.value?.active_projects_count,
        selected: params.value.project_type === 'active',
      },
      {
        label: 'Finished',
        to: { name: 'applications-upcoming', query: { ...route.query, page: 1, project_type: 'finished' } },
        count: upcomingProjects.value?.finished_projects_count,
        selected: params.value.project_type === 'finished',
      },
    ];
  }
});

const isEmpty = computed(() => !applications.value || applications.value.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(upcomingProjectsGuidedEmpty, isEmpty, UPCOMING_FILTER_DEFAULTS);
</script>

<style scoped lang="scss"></style>
